using System;using System.Linq;
namespace XzyBattleStats {static class SmokeChecks {
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 static void Main(string[] args){try{var s=Stats.Decode(args[0]);Check(s.Demo&&s.Uid.StartsWith("DEMO")&&s.Battles.Count==32,"synthetic fixture only");foreach(int mode in Stats.Modes)Check(s.Battles.Count(b=>b.Mode==mode)==8,"four independent modes");var merged=Merge.Combine(s,s);Check(merged.Data.Battles.Count==32,"repeat import does not duplicate records");Check(Stats.Teammates(s,0).Sum(x=>x.Games)==16,"teammate total excludes 1v1");Check(OpponentStats.Rows(s,0).Sum(x=>x.Games)==48,"each opponent counted per battle");Check(Stats.Teammates(s,0).All(t=>t.RoleRows.Sum(r=>r.Games)==t.Games),"teammate role totals");Check(s.Battles.Where(b=>b.Mode==11||b.Mode==21).All(b=>!b.ScoreAfter.HasValue),"matching is not a ranked score");Check(!Stats.TeammateCsv(s,true).Contains("UID"),"teammate CSV hides IDs");Console.WriteLine("PASS synthetic desktop fixture, four modes, repeat merge, teammate/character/opponent counts, ranked score semantics and CSV privacy.");}catch(Exception e){Console.Error.WriteLine(e.Message);Environment.ExitCode=1;}}
}}
